package glitch

import data.glitch_lib

# Define patterns for password-related field names
password_patterns := {"password", "passwd", "pwd", "secret", "credential", "token", "api_key", "auth_token", "activationkey", "api_token", "cache_secret_key", "proxy_password"}

# Check if a variable name contains any password-related pattern
is_password_variable(name) {
    lower_name := lower(name)
    pattern := password_patterns[_]
    contains(lower_name, pattern)
}

# Check if a value is empty (empty string or null)
is_empty_value(value) {
    value.ir_type == "String"
    value.value == ""
} else {
    value.ir_type == "Null"
}

# Main detection rule for empty passwords in variables
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    variables := glitch_lib.all_variables(parent)
    variable := variables[_]

    # Check if the variable name indicates a password-related field
    is_password_variable(variable.name)

    # Check if the value is empty
    is_empty_value(variable.value)

    result := {
        "type": "sec_empty_pass",
        "element": variable,
        "path": parent.path,
        "description": "Empty password in configuration file - Passwords should not be empty. (CWE-258)"
    }
}

